import{_ as i,r as a,o as r,c as d,e as n,a as e,s}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Form Fields - October CMS - 3.x","titleTemplate":false,"description":"Learn about the different form field types.","frontmatter":{"subtitle":"Learn about the different form field types."},"headers":[{"level":2,"title":"Available Fields","slug":"available-fields","link":"#available-fields","children":[]},{"level":2,"title":"Field Properties","slug":"field-properties","link":"#field-properties","children":[{"level":3,"title":"Tab Properties","slug":"tab-properties","link":"#tab-properties","children":[]},{"level":3,"title":"Custom Field Types","slug":"custom-field-types","link":"#custom-field-types","children":[]},{"level":3,"title":"Nested Field Selection","slug":"nested-field-selection","link":"#nested-field-selection","children":[]},{"level":3,"title":"Field Facades","slug":"field-facades","link":"#field-facades","children":[]}]},{"level":2,"title":"Field Conditions","slug":"field-conditions","link":"#field-conditions","children":[{"level":3,"title":"Trigger Events","slug":"trigger-events","link":"#trigger-events","children":[{"level":4,"title":"Multiple Actions","slug":"multiple-actions","link":"#multiple-actions","children":[]},{"level":4,"title":"Multiple Value Conditions","slug":"multiple-value-conditions","link":"#multiple-value-conditions","children":[]},{"level":4,"title":"Wildcard Value Conditions","slug":"wildcard-value-conditions","link":"#wildcard-value-conditions","children":[]},{"level":4,"title":"Multiple Field Values","slug":"multiple-field-values","link":"#multiple-field-values","children":[]},{"level":4,"title":"Referencing Parent Fields","slug":"referencing-parent-fields","link":"#referencing-parent-fields","children":[]}]},{"level":3,"title":"Input Preset Converter","slug":"input-preset-converter","link":"#input-preset-converter","children":[]}]}],"relativePath":"3.x/element/form-fields.md","filePath":"3.x/element/form-fields.md"}'),p={name:"3.x/element/form-fields.md"};function c(u,t,h,f,m,k){const o=a("pre-heading"),l=a("post-heading");return r(),d("div",null,[n(o),t[0]||(t[0]=e("h1",null,"Form Fields",-1)),n(l),t[1]||(t[1]=s(`<p>Form Fields, Form UI and Form Widgets are field definitions used by forms, such as a text input. These are commonly referred to by the following areas:</p><ul><li><a href="./../cms/themes/settings.html">CMS Theme Settings</a></li><li><a href="./../cms/tailor/content-fields.html">Tailor Content Fields</a></li><li><a href="./../extend/forms/form-controller.html">Backend Form Controller</a></li><li><a href="./../extend/forms/relation-controller.html">Backend Relation Controller</a></li></ul><p>All form fields are identified as their individual <strong>type</strong> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">myfield</span><span class="token punctuation">:</span>
        <span class="token key atrule">type</span><span class="token punctuation">:</span> textarea
        <span class="token comment"># ...</span>
</code></pre></div><p>Form Fields contain generic and simple fields. Form UI is for user interface elements that can be included in forms to help with the layout design. Form Widgets will often introduce more complex functionality, it is common for plugins to provide their own custom form widgets. Tailor Fields are fields that are only available inside tailor blueprints.</p><h2 id="available-fields"><a href="#available-fields" class="header-anchor">#</a> Available Fields</h2><p>The following form fields are available:</p>`,7)),t[2]||(t[2]=e("div",{class:"content-list-p",markdown:"1"},[e("p",null,[e("a",{href:"./content/field-mixin.html"},"Mixin"),e("a",{href:"./content/field-entries.html"},"Entries"),e("a",{href:"./form/field-text.html"},"Text"),e("a",{href:"./form/field-number.html"},"Number"),e("a",{href:"./form/field-password.html"},"Password"),e("a",{href:"./form/field-email.html"},"Email"),e("a",{href:"./form/field-textarea.html"},"Textarea"),e("a",{href:"./form/field-dropdown.html"},"Dropdown"),e("a",{href:"./form/field-radio.html"},"Radio List"),e("a",{href:"./form/field-balloon.html"},"Balloon Selector"),e("a",{href:"./form/field-checkbox.html"},"Checkbox"),e("a",{href:"./form/field-checkboxlist.html"},"Checkbox List"),e("a",{href:"./form/field-switch.html"},"Switch"),e("a",{href:"./form/widget-codeeditor.html"},"Code Editor"),e("a",{href:"./form/widget-colorpicker.html"},"Color Picker"),e("a",{href:"./form/widget-datatable.html"},"Data Table"),e("a",{href:"./form/widget-datepicker.html"},"Date Picker"),e("a",{href:"./form/widget-fileupload.html"},"File Upload"),e("a",{href:"./form/widget-markdown.html"},"Markdown Editor"),e("a",{href:"./form/widget-mediafinder.html"},"Media Finder"),e("a",{href:"./form/widget-nestedform.html"},"Nested Form"),e("a",{href:"./form/widget-recordfinder.html"},"Record Finder"),e("a",{href:"./form/widget-relation.html"},"Relation"),e("a",{href:"./form/widget-repeater.html"},"Repeater"),e("a",{href:"./form/widget-richeditor.html"},"Rich Editor"),e("a",{href:"./form/widget-pagefinder.html"},"Page Finder"),e("a",{href:"./form/widget-sensitive.html"},"Sensitive"),e("a",{href:"./form/widget-taglist.html"},"Tag List"),e("a",{href:"./form/widget-currency.html"},"Currency"),e("a",{href:"./form/widget-boxes.html"},"Boxes"),e("a",{href:"./form/ui-section.html"},"Section"),e("a",{href:"./form/ui-hint.html"},"Hint"),e("a",{href:"./form/ui-ruler.html"},"Ruler"),e("a",{href:"./form/ui-partial.html"},"Partial")])],-1)),t[3]||(t[3]=s(`<h2 id="field-properties"><a href="#field-properties" class="header-anchor">#</a> Field Properties</h2><p>For each field you can specify these common properties, where applicable.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>type</strong></td><td>defines how this field should be rendered. Default: <code>text</code>.</td></tr><tr><td><strong>span</strong></td><td>aligns the form field to one side. Options: <code>auto</code>, <code>left</code>, <code>right</code>, <code>row</code>, <code>full</code>. Default: <code>full</code>.</td></tr><tr><td><strong>spanClass</strong></td><td>used with the span <code>row</code> property to display the form as a Bootstrap grid, for example, <code>spanClass: col-4</code>.</td></tr><tr><td><strong>size</strong></td><td>specifies a field size for fields that use it, for example, the textarea field. Options: <code>tiny</code>, <code>small</code>, <code>large</code>, <code>huge</code>, <code>giant</code>.</td></tr><tr><td><strong>placeholder</strong></td><td>if the field supports a placeholder value.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>commentAbove</strong></td><td>places a comment above the field.</td></tr><tr><td><strong>commentHtml</strong></td><td>allow HTML markup inside the comment. Options: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>default</strong></td><td>specify the default value for the field. For <code>dropdown</code>, <code>checkboxlist</code>, <code>radio</code> and <code>balloon-selector</code> widgets, you may specify an option key here to have it selected by default.</td></tr><tr><td><strong>defaultFrom</strong></td><td>takes the default value from the value of another model attribute.</td></tr><tr><td><strong>tab</strong></td><td>assigns the field to a tab.</td></tr><tr><td><strong>cssClass</strong></td><td>assigns a CSS class to the field container.</td></tr><tr><td><strong>autoFocus</strong></td><td>flags the field to be focused when the form loads. Default: <code>false</code>.</td></tr><tr><td><strong>readOnly</strong></td><td>prevents the field from being modified. Options: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>disabled</strong></td><td>prevents the field from being modified and excludes it from the saved data. Options: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>hidden</strong></td><td>hides the field from the view and excludes it from the saved data. Options: <code>true</code>, <code>false</code>.</td></tr><tr><td><strong>stretch</strong></td><td>specifies if this field stretches to fit the parent height.</td></tr><tr><td><strong>context</strong></td><td>specifies what context should be used when displaying the field. Context can also be passed by using an <code>@</code> symbol in the field name, for example, <code>name@update</code>.</td></tr><tr><td><strong>dependsOn</strong></td><td>an array of other field names this field <a href="./../extend/forms/field-dependencies.html">depends on</a>, when the other fields are modified, this field will update.</td></tr><tr><td><strong>changeHandler</strong></td><td>the name of an AJAX handler to call when the field value is changed, optional.</td></tr><tr><td><strong>trigger</strong></td><td>specify conditions for this field using trigger events.</td></tr><tr><td><strong>preset</strong></td><td>allows the field value to be initially set by the value of another field, converted using the input preset converter.</td></tr><tr><td><strong>required</strong></td><td>places a red asterisk next to the field label to indicate it is required. Be sure to use the <a href="./../extend/database/traits.html">validation trait on the model</a> as this is not enforced by the form controller.</td></tr><tr><td><strong>attributes</strong></td><td>specify custom HTML attributes to add to the form field element.</td></tr><tr><td><strong>containerAttributes</strong></td><td>specify custom HTML attributes to add to the form field container.</td></tr><tr><td><strong>order</strong></td><td>a numerical weight when determining the display order, default value increments at 100 points per field.</td></tr><tr><td><strong>permissions</strong></td><td>the <a href="./../extend/backend/permissions.html">permissions</a> that the current backend user must have in order for the field to be used. Supports either a string for a single permission or an array of permissions of which only one is needed to grant access.</td></tr></tbody></table></div><h3 id="tab-properties"><a href="#tab-properties" class="header-anchor">#</a> Tab Properties</h3><p>An example of specifying field definitions in tabs.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token key atrule">username</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> text
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Username
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> User

        <span class="token key atrule">groups</span><span class="token punctuation">:</span>
            <span class="token key atrule">type</span><span class="token punctuation">:</span> relation
            <span class="token key atrule">label</span><span class="token punctuation">:</span> Groups
            <span class="token key atrule">tab</span><span class="token punctuation">:</span> Groups
</code></pre></div><p>For each tab definition, namely <code>tabs</code> and <code>secondaryTabs</code>, you can specify these properties.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>stretch</strong></td><td>specifies if this tab stretches to fit the parent height.</td></tr><tr><td><strong>defaultTab</strong></td><td>the default tab to assign fields to. Default: Misc.</td></tr><tr><td><strong>activeTab</strong></td><td>selected tab when the form first loads, name or index. Default: <code>1</code></td></tr><tr><td><strong>icons</strong></td><td>assign icons to tabs using tab names as the key.</td></tr><tr><td><strong>lazy</strong></td><td>array of tabs to be loaded dynamically when clicked. Useful for tabs that contain large amounts of content.</td></tr><tr><td><strong>identifiers</strong></td><td>array of custom HTML identifiers for targeting the tab. Useful for showing and hiding tabs using JavaScript.</td></tr><tr><td><strong>linkable</strong></td><td>determines if the tabs can be linked using URL fragments. Default: <code>true</code></td></tr><tr><td><strong>cssClass</strong></td><td>assigns a CSS class to the tab container.</td></tr><tr><td><strong>paneCssClass</strong></td><td>assigns a CSS class to an individual tab pane. Value is an array, key is tab index or label, value is the CSS class. It can also be specified as a string, in which case the value will be applied to all tabs.</td></tr></tbody></table></div><p>An example applying properties to tabs.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">tabs</span><span class="token punctuation">:</span>
    <span class="token key atrule">stretch</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
    <span class="token key atrule">defaultTab</span><span class="token punctuation">:</span> User
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> text<span class="token punctuation">-</span>blue

    <span class="token key atrule">lazy</span><span class="token punctuation">:</span>
        <span class="token punctuation">-</span> Groups

    <span class="token key atrule">paneCssClass</span><span class="token punctuation">:</span>
        <span class="token key atrule">1</span><span class="token punctuation">:</span> first<span class="token punctuation">-</span>tab
        <span class="token key atrule">2</span><span class="token punctuation">:</span> second<span class="token punctuation">-</span>tab

    <span class="token key atrule">icons</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>user
        <span class="token key atrule">Groups</span><span class="token punctuation">:</span> icon<span class="token punctuation">-</span>group

    <span class="token key atrule">identifiers</span><span class="token punctuation">:</span>
        <span class="token key atrule">User</span><span class="token punctuation">:</span> userTab

    <span class="token key atrule">fields</span><span class="token punctuation">:</span>
        <span class="token comment"># [...]</span>
</code></pre></div><h3 id="custom-field-types"><a href="#custom-field-types" class="header-anchor">#</a> Custom Field Types</h3><p>There are various native field types that can be used for the <strong>type</strong> setting. It is also possible to render a field directly by specifying the PHP class name of a <a href="./../extend/forms/form-widgets.html">form field widget</a>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">blog_content</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span> Backend\\FormWidgets\\RichEditor
    <span class="token key atrule">size</span><span class="token punctuation">:</span> huge
</code></pre></div><h3 id="nested-field-selection"><a href="#nested-field-selection" class="header-anchor">#</a> Nested Field Selection</h3><div class="language-yaml extra-class"><pre class="language-yaml"><code>avatar<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Avatar
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> will be saved in the Avatar table
</code></pre></div><p>The above example would fetch and save the value in PHP equivalent of <code>$record-&gt;avatar-&gt;name</code> or <code>$record-&gt;avatar[&#39;name&#39;]</code> respectively.</p><h3 id="field-facades"><a href="#field-facades" class="header-anchor">#</a> Field Facades</h3><p>Sometimes you may need to display a field while preventing it from being submitted. A field can be defined as a facade by adding an underscore (_) before the name of the field. These fields are purged automatically and no longer saved to the model, such as with the following <code>_map</code> field.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">address</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title
    <span class="token key atrule">type</span><span class="token punctuation">:</span> text

<span class="token key atrule">_map</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Point your address on the map
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mapviewer
</code></pre></div><h2 id="field-conditions"><a href="#field-conditions" class="header-anchor">#</a> Field Conditions</h2><p>Sometimes you may want to manipulate the value or appearance of a form field under certain conditions, for example, you may want to hide an input if a checkbox is ticked or preset the value of another field.</p><h3 id="trigger-events"><a href="#trigger-events" class="header-anchor">#</a> Trigger Events</h3><p>Trigger Events are defined with the <code>trigger</code> form field property and is a simple browser based solution that uses JavaScript. It allows you to change elements attributes such as visibility or value, based on another elements&#39; state. Here is a sample definition:</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">is_delayed</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send later
    <span class="token key atrule">comment</span><span class="token punctuation">:</span> Place a tick in this box if you want to send this message at a later time.
    <span class="token key atrule">type</span><span class="token punctuation">:</span> checkbox

<span class="token key atrule">send_at</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Send date
    <span class="token key atrule">type</span><span class="token punctuation">:</span> datepicker
    <span class="token key atrule">cssClass</span><span class="token punctuation">:</span> field<span class="token punctuation">-</span>indent
    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
        <span class="token key atrule">field</span><span class="token punctuation">:</span> is_delayed
        <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
</code></pre></div><p>In the above example the <code>send_at</code> form field will only be shown if the <code>is_delayed</code> field is checked. In other words, the field will show (action) if the other form input (field) is checked (condition).</p><p>The <code>trigger</code> definition specifies these properties.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>action</strong></td><td>defines the action applied to this field when the condition is met. Supported values: <code>show</code>, <code>hide</code>, <code>enable</code>, <code>disable</code>, <code>empty</code>, <code>fill[somevalue]</code>.</td></tr><tr><td><strong>field</strong></td><td>reference to the other field name that triggers the action. Example: <code>color</code> or <code>color[]</code>.</td></tr><tr><td><strong>condition</strong></td><td>determines the condition the specified field should satisfy for the condition to be considered <code>true</code>. Supported values: <code>checked</code>, <code>unchecked</code>, <code>value[somevalue]</code>.</td></tr></tbody></table></div><h4 id="multiple-actions"><a href="#multiple-actions" class="header-anchor">#</a> Multiple Actions</h4><p>You may combine multiple actions by separating them with a pipe <code>|</code> symbol. The following will both display and empty the input when the trigger condition is met.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show<span class="token punctuation">|</span>empty
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> checked
    <span class="token key atrule">field</span><span class="token punctuation">:</span> name
</code></pre></div><h4 id="multiple-value-conditions"><a href="#multiple-value-conditions" class="header-anchor">#</a> Multiple Value Conditions</h4><p>When using the <code>value[]</code> condition, you may look for multiple values by passing extra values after the first one, which takes the format <code>value[][]</code>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>csv<span class="token punctuation">]</span><span class="token punctuation">[</span>csv_custom<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_format
</code></pre></div><h4 id="wildcard-value-conditions"><a href="#wildcard-value-conditions" class="header-anchor">#</a> Wildcard Value Conditions</h4><p>You may check the <code>value[]</code> condition matches multiple possible values using a wildcard character (<code>*</code>), for example, <strong>foo*</strong> matches anything that starts with &quot;foo&quot;, and <strong>*bar</strong> matches anything that ends with &quot;bar&quot;.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token important">*.mp4</span><span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> file_name
</code></pre></div><h4 id="multiple-field-values"><a href="#multiple-field-values" class="header-anchor">#</a> Multiple Field Values</h4><p>Some fields, such as <a href="./form/field-checkboxlist.html">Checkbox List</a> and <a href="./form/widget-taglist.html">Tag List</a>, will store their values as an array. When referencing these fields, the field name should use an array suffix (<code>[]</code>) to look at all possible values. For example, if a <code>colors</code> field name supports multiple values, the field name <code>colors[]</code> should be used as a reference.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">trigger</span><span class="token punctuation">:</span>
    <span class="token key atrule">action</span><span class="token punctuation">:</span> show
    <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span>red<span class="token punctuation">]</span><span class="token punctuation">[</span>green<span class="token punctuation">]</span>
    <span class="token key atrule">field</span><span class="token punctuation">:</span> colors<span class="token punctuation">[</span><span class="token punctuation">]</span>
</code></pre></div><h4 id="referencing-parent-fields"><a href="#referencing-parent-fields" class="header-anchor">#</a> Referencing Parent Fields</h4><p>Normally the field name refers to a field in the same level form. For example, if this field is in a <a href="./form/widget-repeater.html">repeater widget</a>, only fields in that same repeater widget will be checked. However, if the field name is preceded by a caret symbol <code>^</code> like: <code>^parent_field</code>, it will refer to a repeater widget or form one level higher than the field itself.</p><p>In the example below, the <code>colors</code> field will be shown when the <code>type</code> field is set to <strong>Complex</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">fields</span><span class="token punctuation">:</span>
    <span class="token key atrule">type</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Type
        <span class="token key atrule">type</span><span class="token punctuation">:</span> dropdown
        <span class="token key atrule">options</span><span class="token punctuation">:</span>
            <span class="token key atrule">1</span><span class="token punctuation">:</span> Simple
            <span class="token key atrule">2</span><span class="token punctuation">:</span> Complex

    <span class="token key atrule">content</span><span class="token punctuation">:</span>
        <span class="token key atrule">label</span><span class="token punctuation">:</span> Content
        <span class="token key atrule">type</span><span class="token punctuation">:</span> nestedform
        <span class="token key atrule">form</span><span class="token punctuation">:</span>
            <span class="token key atrule">fields</span><span class="token punctuation">:</span>
                <span class="token key atrule">colors</span><span class="token punctuation">:</span>
                    <span class="token key atrule">label</span><span class="token punctuation">:</span> Colors
                    <span class="token key atrule">type</span><span class="token punctuation">:</span> colorpicker
                    <span class="token key atrule">trigger</span><span class="token punctuation">:</span>
                        <span class="token key atrule">action</span><span class="token punctuation">:</span> show
                        <span class="token key atrule">field</span><span class="token punctuation">:</span> ^type
                        <span class="token key atrule">condition</span><span class="token punctuation">:</span> value<span class="token punctuation">[</span><span class="token number">2</span><span class="token punctuation">]</span>
</code></pre></div><div class="custom-block tip"><p>Additionally, if more than one caret <code>^</code> is used, it will refer that many levels higher: <code>^^grand_parent_field</code>, <code>^^^grand_grand_parent_field</code>, etc.</p></div><h3 id="input-preset-converter"><a href="#input-preset-converter" class="header-anchor">#</a> Input Preset Converter</h3><p>The input preset converter is defined with the <code>preset</code> form field property and allows you to convert text entered into an element to a URL, slug or file name value in another input element.</p><p>In this example we will automatically fill out the <code>url</code> field value when a user enters text in the <code>title</code> field. If the text <strong>Hello world</strong> is typed in for the Title, the URL will follow suit with the converted value of <strong>/hello-world</strong>. This behavior will only occur when the destination field (<code>url</code>) is empty and untouched.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">title</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Title

<span class="token key atrule">url</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> URL
    <span class="token key atrule">preset</span><span class="token punctuation">:</span>
        <span class="token key atrule">field</span><span class="token punctuation">:</span> title
        <span class="token key atrule">type</span><span class="token punctuation">:</span> url
</code></pre></div><p>Alternatively, the <code>preset</code> value can also be a string that refers to the <strong>field</strong> only, the <code>type</code> option will then default to <strong>slug</strong>.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">slug</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Slug
    <span class="token key atrule">preset</span><span class="token punctuation">:</span> title
</code></pre></div><p>The following options are available for the <code>preset</code> option:</p><div class="table"><table tabindex="0"><thead><tr><th>Option</th><th>Description</th></tr></thead><tbody><tr><td><strong>field</strong></td><td>defines the other field name to source the value from.</td></tr><tr><td><strong>type</strong></td><td>specifies the conversion type. See below for supported values.</td></tr><tr><td><strong>prefixInput</strong></td><td>optional, prefixes the converted value with the value found in the supplied input element using a CSS selector.</td></tr></tbody></table></div><p>Following are the supported types:</p><div class="table"><table tabindex="0"><thead><tr><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>exact</strong></td><td>copies the exact value</td></tr><tr><td><strong>slug</strong></td><td>formats the copied value as a slug</td></tr><tr><td><strong>url</strong></td><td>same as slug but prefixed with a /</td></tr><tr><td><strong>camel</strong></td><td>formats the copied value with camelCase</td></tr><tr><td><strong>file</strong></td><td>formats the copied value as a file name with whitespace replaced with dashes</td></tr></tbody></table></div>`,54))])}const b=i(p,[["render",c]]);export{y as __pageData,b as default};
